class Solution {
  public long countMajoritySubarrays(int[] nums, int target) {
    int n = nums.length;
    long[] bit = new long[2 * n + 3];
    int offset = n + 1;
    long total = 0;
    int sum = 0;
    for (int i = offset; i < bit.length; i += i & -i) bit[i]++;
    for (int x : nums) {
      sum += x == target ? 1 : -1;
      // count previous prefix sums strictly smaller than the current one
      long smaller = 0;
      for (int i = sum + offset - 1; i > 0; i -= i & -i) smaller += bit[i];
      total += smaller;
      for (int i = sum + offset; i < bit.length; i += i & -i) bit[i]++;
    }
    return total;
  }
}
